def consulta():
    return '''<div id="previa" class="preview" aria-live="polite">Passe o mouse em um ponto para ler as manchetes. Clique para consultar a lista completa. A busca também permite consultar as notícias pelo teclado.</div><aside id="consulta" hidden role="dialog" aria-modal="false" aria-labelledby="lista-titulo"><div class="drawer-head"><h3 id="lista-titulo" tabindex="-1">Notícias</h3><button id="fechar" aria-label="Fechar notícias">Fechar</button></div><p class="muted">O assunto é uma classificação automática por palavras da manchete. A base não contém o texto integral das matérias. O link leva à fonte original, quando disponível.</p><label for="lista-busca">Buscar por título, assunto, empresa ou fonte</label><input type="search" id="lista-busca"><div id="lista"></div><div class="pagination"><button id="anterior">Anterior</button><span id="paginacao" class="muted"></span><button id="proxima">Próxima</button></div></aside>'''

def payload(d,t):
    n=d['noticias'].merge(d['mapa'][['source_id','trade_date']],on='source_id',validate='one_to_one')
    campos=['source_id','stock','news_date','trade_date','headline','url','publisher','classe_finbert','escore_sentimento','assunto']
    pr=d['principal'][['stock','trade_date','ano','n_noticias','escore_sentimento','retorno_pct','retorno_absoluto_pct','classe_sentimento','intensidade_media','polarizacao_liquida','key']]
    out={k:registros(v) for k,v in t.items()}
    out.update(noticias=registros(n[campos]),principal=registros(pr),diario=registros(d['diario']))
    return out

def html_pagina(conteudo,dados,titulo='Sentimento das notícias e retornos de ações',individual=False):
    lib=(RAIZ/'vendor/plotly-cartesian.min.js').read_text(encoding='utf-8')
    driver=(RAIZ/'tools/graficos_final.js').read_text(encoding='utf-8')
    data=json.dumps(dados,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
    return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+escape(titulo)+'</title><style>'+CSS+'</style><script>'+lib+'</script></head><body>'+controles()+'<main>'+conteudo+consulta()+'</main><script>window.DADOS='+data+';</script><script>'+driver+'</script></body></html>'

def textos(d,t):
    cobertura=t['q1_anual'].pivot(index='stock',columns='ano',values='n').reset_index();cobertura['Total']=cobertura[[2017,2018,2019]].sum(axis=1)
    comp=t['q2_classes'].copy();comp['Total']=comp.iloc[:,1:].sum(axis=1)
    corr=t['q6_correlacoes'].copy();rhos=corr.loc[corr.periodo.eq('2017–2019'),'rho']
    partes=[]
    partes.append(('inicio','''<p class="kicker">FGV EMAp · Análise Exploratória de Dados e Visualização · 2026.2</p><h1>Sentimento das notícias e retornos de cinco ações dos EUA</h1><p class="lead">Uma análise exploratória de NVDA, NFLX, BAC, JNJ e KO entre 2017 e 2019</p><p>Caio Ladislau do Couto, Alice Barros Lourencini Palaoro e Mateus Henrique da Costa Resende<br>Professor João Rulff · Entrega final · 11 de novembro de 2026</p><p><a href="https://github.com/caiocouto30-boop/projeto-sentimento-acoes">Repositório do projeto</a></p><nav aria-label="Seções">'''+''.join(f'<a href="#sec-q{i}">Pergunta {i}</a>' for i in range(1,8))+'''<a href="#conclusao">Conclusão</a></nav><h2>Resumo</h2><p>Investigamos associações entre o sentimento de manchetes financeiras e o retorno do primeiro pregão posterior à data da notícia. Combinamos notícias do Kaggle, probabilidades de um FinBERT pronto e cotações ajustadas do Yahoo Finance. Após retirar quatro duplicatas, conservamos 6.552 associações manchete–empresa e comparamos 2.387 pares empresa/pregão com janela completa. A cobertura é desigual, as distribuições de retorno por classe se sobrepõem e as correlações entre escore e retorno são pequenas. Filtros de quantidade e retrospectividade alteram a amostra e alguns sinais. Uma análise adicional distingue polarização líquida e intensidade média, também com associações pequenas. Os resultados descrevem este corpus e não estabelecem causalidade ou capacidade de previsão.</p><h2>1. Problema, motivação e hipóteses</h2><p>Notícias podem acompanhar mudanças nas expectativas sobre uma empresa, enquanto muitas manchetes já descrevem movimentos de mercado observados. Explorar a relação entre o tom dos textos e os preços exige conhecer a cobertura, definir a unidade de análise e alinhar as datas. O objetivo é construir uma narrativa visual capaz de mostrar padrões e exceções, usando o modelo de linguagem como ferramenta de preparação.</p><p><strong>H1.</strong> A cobertura varia entre empresas e períodos. <strong>H2.</strong> Maior intensidade de sentimento acompanha retornos absolutos posteriores maiores. <strong>H3.</strong> As associações diferem entre empresas e anos. São hipóteses exploratórias, sem testes confirmatórios ou promessa de confirmação. A intensidade média acrescentada na versão final é uma análise de sensibilidade posterior à definição original.</p><h2>2. Dados e unidades de análise</h2><p>A base <em>Daily Financial News for 6000+ Stocks</em>, de Miguel Aenlle, fornece manchete, data civil, URL, fonte e ticker. O recorte bruto tem 6.556 registros. A limpeza remove quatro repetições dentro de empresa/data/manchete, deixando <strong>6.552 associações</strong> e <strong>6.019 textos distintos</strong>. Uma manchete associada a várias empresas permanece em cada vínculo, sem representar textos independentes.</p><p>As cotações incluem 754 pregões por empresa no período, totalizando <strong>3.770 pares empresa/pregão</strong>. O snapshot coletado em 09/10/2026 inclui margens entre 15/12/2016 e 10/01/2020 para calcular retornos e tratar as bordas. A análise temporal da Q3 usa 2.569 pares empresa/data civil. As Q4–Q7 usam um retorno por empresa/pregão, evitando repetir o mesmo resultado para cada manchete.</p><h2>3. Preparação, medidas e alinhamento</h2><p>Normalizamos espaços, preservamos identificadores e textos originais e mantemos vínculos compartilhados entre empresas. Aplicamos o modelo pronto <code>ProsusAI/finbert</code>, revisão <code>4556d13015211d73dccd3fdd39d39232506f3e43</code>, sem treinamento adicional. Guardamos probabilidades de positivo, negativo e neutro. O escore de cada manchete é a diferença entre as duas primeiras probabilidades. A classe agregada corresponde à maior probabilidade média, com empate explícito à tolerância de 10⁻⁸. Escore próximo de zero não define neutralidade.</p><p class="formula">sᵢ = Pᵢ(positivo) − Pᵢ(negativo)<br>s̄ = média(sᵢ) · polarização líquida = |s̄| · intensidade média = média(|sᵢ|)<br>rₜ = 100 × (P ajustadoₜ / P ajustado do pregão anterior − 1) · oscilação = |rₜ|</p><p>O planejamento definia intensidade como o módulo do escore agregado. Preservamos esse cálculo, agora nomeado <strong>polarização líquida</strong>, e acrescentamos a média dos módulos individuais. Por exemplo matemático, escores +0,9 e −0,9 produzem polarização zero e intensidade média 0,9. A nova medida evita cancelamento, mas ainda depende das probabilidades do modelo e não mede toda a intensidade emocional de um texto.</p><p>Como os horários não são confiáveis, cada notícia de data <em>d</em> aponta para o primeiro pregão estritamente posterior, <em>t &gt; d</em>. Reagrupamos as manchetes por empresa/pregão com pesos iguais antes de calcular sentimento, classe e contagem. Dias sem notícias ficam com sentimento ausente. Três pares com notícias têm janela inicial incompleta, restando <strong>2.387 pares elegíveis</strong>. Seis notícias de 31/12/2019 apontam para janeiro de 2020 e ficam fora das comparações principais.</p><p>A revisão dirigida de sentimento já registrada contém 50 manchetes, 39 concordâncias e 11 divergências. Seleção dirigida, um único revisor e exposição às previsões impedem tratar 39/50 como acurácia geral. Probabilidades softmax também não são probabilidades calibradas de acerto. O modelo avalia a manchete inteira, não o efeito específico para cada empresa citada.</p><div class="note interactive-hint"><strong>Como explorar.</strong> Use empresa e ano no topo. Passe o mouse para consultar manchetes e clique para abrir a lista completa, com assunto, fonte e link. O assunto é sugerido por regras lexicais sobre a manchete. A consulta por busca e as tabelas oferecem acesso sem depender do mouse. As tabelas do artigo mantêm a amostra completa, mesmo quando os gráficos estão filtrados.</div>'''))
    partes.append(('q1','''<h2 id="sec-q1">4. Pergunta 1 · Como a cobertura se distribui?</h2><p><strong>Transformação.</strong> Contamos associações por empresa/ano e empresa/mês. Reindexamos os 36 meses para mostrar zeros de cobertura. A cor do mapa representa a contagem, com a mesma escala em todos os filtros.</p>'''+figura('q1','Cada célula representa uma empresa/mês pela data da notícia. Passe o mouse para ver exemplos ou clique para consultar as manchetes do grupo.')+table(cobertura,0)+'''<p><strong>Resposta.</strong> Netflix concentra 2.344 associações e NVIDIA 1.647, enquanto Coca-Cola tem 644. H1 recebe apoio descritivo pela variação de cobertura entre empresas e meses. Essa desigualdade e as lacunas temporais tornam comparações de totais pouco informativas sobre sentimento. Por isso, as próximas perguntas comparam proporções dentro de cada empresa e informam o tamanho das amostras.</p><p><strong>Limite.</strong> Ausência no corpus significa ausência de notícia registrada nesta base. Não demonstra ausência de informação no mercado e não recebe sentimento neutro.</p>'''))
    partes.append(('q2','''<h2 id="sec-q2">5. Pergunta 2 · Como se compõe o sentimento?</h2><p><strong>Transformação.</strong> Contamos a classe FinBERT de cada associação e dividimos pelo total da respectiva empresa. Barras de 100% permitem comparar composição apesar das diferenças de cobertura.</p>'''+figura('q2','Proporções por empresa. O hover informa contagem e denominador. Clique em um segmento para consultar seus títulos.')+table(comp,0)+'''<p><strong>Resposta.</strong> Neutro é a classe mais frequente em todas as empresas. No conjunto das associações são 3.598 neutras, 1.613 positivas e 1.341 negativas. A predominância de uma classe descreve a classificação deste corpus, sem indicar a direção futura do preço.</p><p><strong>Limite.</strong> A mesma classificação pode acompanhar várias empresas citadas, e o modelo pode errar títulos ambíguos ou financeiros muito específicos.</p>'''))
    partes.append(('q3','''<h2 id="sec-q3">6. Pergunta 3 · Quando o sentimento apresenta extremos?</h2><p><strong>Transformação.</strong> Agregamos o escore por empresa/data civil e conservamos a quantidade de manchetes. Localizamos máximo e mínimo por empresa, primeiro com qualquer suporte e depois exigindo três notícias. A série usa uma escala comum de −1 a +1 e não conecta dias sem observação.</p>'''+figura('q3','Cada ponto representa uma empresa/data civil. O seletor de datas permite aproximar um intervalo. No hover aparece uma manchete real; a lista completa explica de quais textos vem cada agregado.')+table(t['q3_extremos'].loc[t['q3_extremos'].minimo_noticias.eq(3),['stock','extremo','news_date','escore_sentimento','n_noticias']])+'''<p><strong>Resposta.</strong> Os extremos sem restrição podem ter suporte de uma única manchete, e a exigência de três notícias muda os dias selecionados. Consultar os textos permite distinguir eventos corporativos, avaliações de analistas e relatos de mercado por trás de escores parecidos. O valor extremo do modelo não basta para caracterizar um evento relevante.</p><p><strong>Limite.</strong> Um escore agregado cancela tons opostos e a média muda conforme a cobertura. Os títulos mostram o contexto disponível, mas não substituem a leitura das matérias completas.</p>'''))
    partes.append(('q4','''<h2 id="sec-q4">7. Pergunta 4 · O retorno posterior difere entre classes?</h2><p><strong>Transformação.</strong> Usamos os 2.387 pares elegíveis. Em cada empresa, comparamos retornos por classe de maior probabilidade média. Os boxplots mostram mediana, intervalo interquartil e cercas de 1,5 vezes esse intervalo. Os pontos conservam os retornos individuais, inclusive extremos, com escalas comuns.</p>'''+figura('q4','Um ponto por empresa/pregão. O hover e o clique dos pontos consultam as manchetes que formaram sua classe. O n no título de cada painel se refere aos pares mostrados.')+table(t['q4_retornos_classes'][['stock','classe_sentimento','n','mediana','q1','q3']])+'''<p><strong>Resposta.</strong> As distribuições por classe se sobrepõem e as medianas não apresentam uma ordenação negativa–neutra–positiva uniforme entre empresas. Não aparece uma ordenação uniforme entre as classes e os retornos nesta comparação descritiva. Um retorno individual favorável ou desfavorável não valida a classificação como sinal de previsão.</p><p><strong>Limite.</strong> As classes têm tamanhos diferentes, as observações compartilham choques de mercado e não controlamos fatores setoriais, mercado ou informação já incorporada ao preço.</p>'''))
    partes.append(('q5','''<h2 id="sec-q5">8. Pergunta 5 · Mais notícias ou mais intensidade acompanham maiores oscilações?</h2><p><strong>Transformação.</strong> Comparamos a quantidade de manchetes e a polarização líquida com o retorno absoluto do pregão de resposta. O seletor permite substituir a medida original pela intensidade média. Calculamos Spearman dentro de cada empresa, usando postos médios nos empates.</p><label>Medida no segundo painel <select id="medida"><option value="polarizacao_liquida">Polarização líquida = |média(sᵢ)|</option><option value="intensidade_media">Intensidade média = média(|sᵢ|)</option></select></label>'''+figura('q5','Os dois painéis usam os mesmos pares e a mesma escala de retorno absoluto. Cada ponto conserva todas as manchetes do agregado para consulta.')+table(t['q5_associacoes'],4)+'''<p><strong>Resposta.</strong> A associação entre quantidade e oscilação é positiva nas cinco empresas, porém pequena, de aproximadamente 0,030 a 0,161. A polarização líquida tem coeficientes entre −0,010 e 0,055. A intensidade média acrescentada varia de −0,034 a 0,080. A quantidade apresenta associação descritiva fraca. H2 não recebe apoio uniforme das medidas de sentimento neste recorte.</p><p><strong>Limite.</strong> Resultado fraco para essas medidas não prova inexistência de toda relação possível. Cobertura editorial pode aumentar quando o mercado já está agitado, e nenhuma das duas medidas esgota o conceito de intensidade das notícias.</p>'''))
    partes.append(('q6','''<h2 id="sec-q6">9. Pergunta 6 · As associações se repetem entre empresas e anos?</h2><p><strong>Transformação.</strong> Calculamos Spearman entre escore agregado e retorno por empresa/ano do pregão, além do período completo. O mapa mantém a escala de −1 a +1 e mostra coeficiente e n. Clique em uma célula para abrir sua dispersão de apoio. O seletor global de ano não altera este mapa, pois sua função é comparar os anos.</p>'''+figura('q6','A comparação anual usa os pregões de 2017, 2018 e 2019. A coluna do período completo se sobrepõe às colunas anuais e não é uma quarta amostra independente.')+table(corr,4)+'''<p><strong>Resposta.</strong> No período completo, os coeficientes vão de aproximadamente −0,041 em NVIDIA a +0,058 em Netflix. Ao dividir por ano, sinais e magnitudes mudam. Em NVIDIA, 2019 tem coeficiente de −0,153, enquanto 2017 e 2018 são próximos de zero ou positivos. H3 é compatível com essa heterogeneidade descritiva, sem demonstrar diferenças estatisticamente confirmadas entre grupos.</p><p><strong>Limite.</strong> Divisões menores são mais sensíveis a observações extremas e à cobertura. Examinamos várias comparações sem testes de significância, correção de multiplicidade ou estimação causal.</p>'''))
    partes.append(('q7','''<h2 id="sec-q7">10. Pergunta 7 · Os padrões resistem aos filtros?</h2><p><strong>Transformação.</strong> A regra textual preservada identifica relatos explícitos de cotação ou oscilação já observada, sem usar retornos ou escores como entrada. Começamos pelas mesmas janelas elegíveis, excluímos os textos marcados e <strong>reagregamos</strong> probabilidades, classe, escore, intensidade e contagem. Só então aplicamos o mínimo de três notícias. Um grupo que perde todas as manchetes sai da comparação. Duas variantes adicionais também excluem textos ambíguos.</p><label>Associação <select id="metrica-robustez"><option>Escore × retorno</option><option>Polarização × |retorno|</option><option>Quantidade × |retorno|</option><option>Intensidade média × |retorno|</option></select></label>'''+figura('q7','Quatro cenários principais no período completo de 2017–2019. Formas e cores identificam os cenários. O hover mostra o n de cada empresa. O seletor global de ano não modifica esta comparação de robustez.')+table(t['q7_resumo_cenarios'],1)+'''<p><strong>Resposta.</strong> O mínimo de três conserva 783 dos 2.387 pares, cerca de 32,8%. O filtro de retrospectivas identificadas conserva 2.271 pares. A combinação retém 697, cerca de 29,2%. Coeficientes e alguns sinais mudam, sem surgir uma associação uniforme entre as empresas. O filtro de quantidade altera substancialmente a composição da amostra e não representa apenas uma versão mais precisa da mesma população.</p><p><strong>Limite.</strong> A regra automática não teve validação humana independente. Pode deixar passar retrospectivas e excluir relatos mistos. O grupo não deve apresentar o filtro como remoção de todas as notícias retrospectivas. As variantes que excluem ambiguidades são sensibilidades adicionais, sem prioridade metodológica automática. A retenção por empresa/ano e todos os coeficientes estão nos CSVs que acompanham o trabalho.</p>'''))
    partes.append(('fim','''<h2 id="conclusao">11. Conclusões e limitações</h2><p>A cobertura difere entre empresas e ao longo do tempo. A classe neutra predomina, mas os retornos posteriores por classe se sobrepõem. O escore agregado apresenta correlações pequenas com o retorno, com sinais variáveis entre anos. Quantidade de notícias acompanha a oscilação de forma positiva e fraca, enquanto polarização líquida e intensidade média permanecem pouco associadas ao retorno absoluto. Os filtros reduzem a amostra e mudam algumas associações.</p><p>H1 recebeu apoio descritivo: a cobertura varia entre empresas e períodos. H2 não apresentou apoio uniforme para as medidas de sentimento. H3 encontrou heterogeneidade descritiva compatível com a hipótese, sem comprovação inferencial. Resultados fracos ou inconclusivos não estabelecem a falsidade universal das hipóteses nem a ausência de toda relação possível entre notícias e preços. A conclusão se restringe às medidas, ao corpus e ao alinhamento estudados.</p><p>Recomendamos aprofundamentos com horários confiáveis, validação humana independente do filtro de retrospectivas e sentimento orientado à empresa mencionada. Comparações futuras podem controlar o retorno de mercado e distinguir tipos de evento, com hipóteses e procedimentos definidos previamente. Este estudo não avalia uma estratégia de negociação, não mede desempenho fora da amostra e não sustenta recomendações de investimento.</p><p>As principais limitações são seleção e cobertura do corpus, manchetes compartilhadas, erros e falta de calibração do FinBERT, ausência de ordenação intradiária, choques comuns de mercado, dependência temporal e incerteza do filtro textual. Retorno absoluto representa oscilação diária, não uma medida completa de volatilidade.</p><h2>12. Reprodutibilidade e retorno incorporado</h2><p>O notebook acompanha o artigo, e a análise pode ser refeita com os snapshots e probabilidades incluídos, sem nova inferência do modelo. Cada seção informa transformação, gráfico, resposta e limite. Os arquivos de dados originais permanecem preservados. As verificações refazem a limpeza, conferem o cache, o primeiro pregão posterior, os retornos, a agregação e a contagem dos cenários.</p><p>O retorno do professor foi incorporado à consulta de manchetes: hover com título e assunto, clique com lista completa, fonte, datas e URL. Os temas são sugestões lexicais transparentes. A apresentação acompanha um roteiro de dez minutos. A declaração de contribuições acompanha o pacote em formato editável e ainda deve receber a divisão efetiva do trio.</p><h2>Referências</h2><ol><li>Miguel Aenlle. <a href="https://www.kaggle.com/datasets/miguelaenlle/massive-stock-news-analysis-db-for-nlpbacktests">Daily Financial News for 6000+ Stocks</a>. Recorte e identificadores preservados no projeto.</li><li>Yahoo Finance. Cotações coletadas com <a href="https://github.com/ranaroussi/yfinance">yfinance</a>, snapshot de 09/10/2026.</li><li>ProsusAI. <a href="https://huggingface.co/ProsusAI/finbert/tree/4556d13015211d73dccd3fdd39d39232506f3e43">FinBERT, revisão utilizada</a>.</li><li>Araci, D. <a href="https://arxiv.org/abs/1908.10063">FinBERT: Financial Sentiment Analysis with Pre-trained Language Models</a>, 2019.</li><li><a href="https://github.com/gerrymanoim/exchange_calendars">exchange_calendars</a>. Calendário XNYS na preparação original.</li><li><a href="https://pandas.pydata.org/docs/">pandas</a> e <a href="https://github.com/plotly/plotly.js">Plotly.js</a>. Agregações, postos e visualizações.</li><li>João Rulff. Enunciado do Projeto Final de Análise Exploratória de Dados e Visualização, FGV EMAp, 2026.2. Orientações fornecidas pelo professor.</li></ol>'''))
    return partes

class Vista:
    def __init__(self,q,tabela=None): self.q=q;self.tabela=tabela
    def _repr_html_(self):
        d=preparar();t=tabelas(d);dados=payload(d,t)
        extra=''
        if self.q=='q5':extra='<select id="medida"><option value="polarizacao_liquida">Polarização líquida</option><option value="intensidade_media">Intensidade média</option></select>'
        if self.q=='q7':extra='<select id="metrica-robustez"><option>Escore × retorno</option><option>Polarização × |retorno|</option><option>Quantidade × |retorno|</option><option>Intensidade média × |retorno|</option></select>'
        body=extra+figura(self.q,'Passe o mouse ou clique para consultar os títulos.')
        html=html_pagina(body,dados)
        zipped=base64.b64encode(gzip.compress(html.encode('utf-8'),mtime=0)).decode('ascii')
        loader='<html><body><p>Carregando gráfico offline…</p><script>(async()=>{const b=Uint8Array.from(atob("'+zipped+'"),c=>c.charCodeAt(0));const txt=await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream("gzip"))).text();document.open();document.write(txt);document.close();})().catch(e=>document.body.textContent=e.message);</script></body></html>'
        result='<iframe title="Gráfico interativo '+self.q+'" style="border:0;width:100%;height:900px" srcdoc="'+escape(loader,quote=True)+'"></iframe>'
        if self.tabela is not None: result+=table(self.tabela)
        return result

def celula(tipo,source,cid):
    c=dict(cell_type=tipo,id=cid,metadata={},source=source.splitlines(keepends=True))
    if tipo=='code':c.update(execution_count=None,outputs=[])
    return c

def montar():
    d=preparar();t=tabelas(d);exportar(d,t);partes=textos(d,t);dados=payload(d,t)
    (RAIZ/'artigo_interativo.html').write_text(html_pagina(''.join(v for _,v in partes),dados),encoding='utf-8',newline='\n')
    cells=[celula('markdown',partes[0][1],'abertura'),celula('code',"from pathlib import Path\nimport sys\nRAIZ = Path.cwd().parent if Path.cwd().name == 'notebooks' else Path.cwd()\nsys.path.insert(0, str(RAIZ / 'tools'))\nfrom analise_final import preparar, tabelas, exportar\nfrom montar_entrega import Vista\ndados = preparar()\nt = tabelas(dados)\nverificacao = exportar(dados, t)\nverificacao",'preparacao')]
    nomes={'q1':'q1_anual','q2':'q2_classes','q3':'q3_extremos','q4':'q4_retornos_classes','q5':'q5_associacoes','q6':'q6_correlacoes','q7':'q7_resumo_cenarios'}
    for q,body in partes[1:-1]:
        # Texto acadêmico e gráfico usam a mesma fonte no notebook e no HTML.
        import re
        antes,depois=body.split('<figure>',1)
        depois=depois.split('</figure>',1)[1]
        antes=re.sub(r'<label>.*?</label>','',antes,flags=re.S)
        depois=re.sub(r'<div class="table-scroll">.*?</div>','',depois,flags=re.S)
        cells.append(celula('markdown',antes,q+'-metodo'))
        cells.append(celula('code',f"Vista('{q}', t['{nomes[q]}'])",q+'-grafico'))
        cells.append(celula('markdown',depois,q+'-analise'))
    cells.append(celula('markdown',partes[-1][1],'conclusao'))
    nb=dict(cells=cells,metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':sys.version.split()[0]}},nbformat=4,nbformat_minor=5)
    (RAIZ/'notebooks/00_artigo.ipynb').write_text(json.dumps(nb,ensure_ascii=False,indent=1),encoding='utf-8')
    (RAIZ/'docs/analise_final/dados_graficos.json').write_text(json.dumps(dados,ensure_ascii=False,separators=(',',':')),encoding='utf-8')
    return d,t

if __name__=='__main__':
    d,t=montar();print('Artigo HTML e notebook final gerados. Dados: 6.552 associações; 2.387 pares principais.')
